content:
{
  "summary": "Created a map of three approaches to life’s meaning, with a question for exploring your own answer.",
  "operations": [
    {
      "op": "create",
      "object": {
        "id": "meaning_question",
        "kind": "text",
        "title": "Meaning of life?",
        "text": "There’s no single agreed answer. “Does life have an ultimate purpose?” and “What makes a life worth living?” are different questions—you can explore one without settling the other.",
        "x": 30,
        "y": 20,
        "width": 1020,
        "height": 100,
        "color": "ink"
      }
    },
    {
      "op": "create",
      "object": {
        "id": "meaning_approaches",
        "kind": "region",
        "title": "Three approaches · they can overlap",
        "x": 20,
        "y": 140,
        "width": 1040,
        "height": 245,
        "color": "blue"
      }
    },
    {
      "op": "create",
      "object": {
        "id": "discover_meaning",
        "kind": "token",
        "title": "Discover meaning",
        "text": "Purpose or value exists beyond our choices—in faith, a larger order, or moral truth. Our task is to discover and respond to it.",
        "x": 40,
        "y": 195,
        "width": 310,
        "height": 165,
        "color": "blue"
      }
    },
    {
      "op": "create",
      "object": {
        "id": "create_meaning",
        "kind": "token",
        "title": "Create meaning",
        "text": "Meaning takes shape through choices, commitments, and responsibility. It need not arrive as a purpose assigned in advance.",
        "x": 385,
        "y": 195,
        "width": 310,
        "height": 165,
        "color": "plum"
      }
    },
    {
      "op": "create",
      "object": {
        "id": "live_meaning",
        "kind": "token",
        "title": "Live meaning",
        "text": "Love, care, curiosity, and worthwhile work can make life meaningful—even without a final explanation of the universe.",
        "x": 730,
        "y": 195,
        "width": 310,
        "height": 165,
        "color": "moss"
      }
    },
    {
      "op": "create",
      "object": {
        "id": "meaning_start",
        "kind": "text",
        "title": "A personal starting point",
        "text": "What feels worth loving, understanding, or protecting in your life? Use a concrete example to test these approaches. Your answer can be a commitment, not a complete theory.",
        "x": 40,
        "y": 410,
        "width": 1000,
        "height": 110,
        "color": "ink"
      }
    }
  ],
  "actions": [
    {
      "label": "Compare philosophical views",
      "instruction": "Add contrasting philosophical examples to the three existing approaches, showing where they disagree without ranking them."
    },
    {
      "label": "Test whether meaning needs permanence",
      "instruction": "Add the claim “If something ends, it cannot really matter” and a counterexample, then connect them to the approaches they challenge or support."
    }
  ]
}
